mapper.select:
SELECT  FROM template

	channel = #{channel}

ORDER BY template_id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE template
SET name = #{name}, subject = #{subject}, body = #{body}, ad_yn = #{adYn}, updated_at = now()
WHERE template_id = #{templateId}

mapper.select:
SELECT EXISTS (
	SELECT 1 FROM campaign c
	WHERE c.status IN ('SCHEDULED', 'ACTIVE', 'PAUSED')
	  AND (
	      c.template_id = #{templateId}
	      OR EXISTS (
	          SELECT 1 FROM workflow_step ws
	          WHERE ws.campaign_id = c.campaign_id
	            AND ws.config_json ->> 'templateId' = #{templateId}::text
	      )
	  )
)

SELECT EXISTS (
	SELECT 1 FROM campaign WHERE template_id = #{templateId}
	UNION ALL
	SELECT 1 FROM workflow_step WHERE config_json ->> 'templateId' = #{templateId}::text
	UNION ALL
	SELECT 1 FROM track_link WHERE template_id = #{templateId}
)
